  { id:'n1082', tema:'tarea1', p:'¿Desde qué año es rey Felipe VI?', o:['Desde 1975','Desde 2014','Desde 2020'], c:1, exp:'Felipe VI es rey de España desde el 19 de junio de 2014, cuando su padre Juan Carlos I abdicó.' },
  { id:'n1083', tema:'tarea1', p:'¿Quién regula el tráfico en los pueblos y ciudades?', o:['La Guardia Civil','Protección Civil','La Policía Local'], c:2, exp:'La Policía Local es competente para regular y ordenar el tráfico dentro de los núcleos urbanos.' },
  { id:'n1084', tema:'tarea1', p:'¿Quién puede presentar una queja al Defensor del Pueblo?', o:['Solo los ciudadanos legalmente residentes','Solo los españoles mayores de 18 años','Todos los ciudadanos, españoles o extranjeros'], c:2, exp:'Cualquier persona, española o extranjera, mayor o menor de edad, puede acudir al Defensor del Pueblo.' },
  { id:'n1085', tema:'tarea1', p:'En España el voto en las elecciones es…', o:['un derecho','un deber','una obligación'], c:0, exp:'El voto es un derecho constitucional de los ciudadanos españoles, no una obligación.' },
  { id:'n1086', tema:'tarea1', p:'¿Quién vigila el tráfico en las carreteras?', o:['La Guardia Civil','La Policía Nacional','El Ejército de Tierra'], c:0, exp:'La Guardia Civil, a través de la Agrupación de Tráfico, es la responsable de vigilar las carreteras.' },
  { id:'n1087', tema:'tarea1', p:'¿Qué organismo se encarga de recaudar los impuestos?', o:['El Tribunal de Cuentas','La Agencia Tributaria','El Consejo Económico y Social'], c:1, exp:'La Agencia Estatal de Administración Tributaria (AEAT) se encarga de recaudar los impuestos.' },
  { id:'n1088', tema:'tarea1', p:'¿Dónde se publican las leyes nacionales?', o:['En el boletín del Instituto Nacional de Estadística','En el Portal de la Administración Electrónica','En el Boletín Oficial del Estado (BOE)'], c:2, exp:'El Boletín Oficial del Estado (BOE) es el diario oficial del Estado español donde se publican las leyes.' },
  { id:'n1089', tema:'tarea1', p:'¿Cómo se llaman los órganos de gobierno que solo existen en Canarias?', o:['Cabildos','Consejos insulares','Diputaciones'], c:0, exp:'Los Cabildos son los órganos de gobierno propios de cada isla en Canarias.' },
  { id:'n1090', tema:'tarea1', p:'¿Cuál de estos trámites administrativos puede realizarse en la sede electrónica?', o:['Tramitar el DNI','Renovar el pasaporte','Pagar los impuestos'], c:2, exp:'Pagar los impuestos es uno de los trámites que puede realizarse a través de la sede electrónica de la Agencia Tributaria.' },
  { id:'n1091', tema:'tarea1', p:'¿Cuál es el número de teléfono de información de la Administración General del Estado?', o:['010','060','091'], c:1, exp:'El 060 es el número de atención telefónica de la Administración General del Estado.' },
  { id:'n1092', tema:'tarea1', p:'España está organizada en…', o:['cantones','comunidades autónomas','estados federales'], c:1, exp:'España está organizada territorialmente en 17 comunidades autónomas y 2 ciudades autónomas.' },
  { id:'n1093', tema:'tarea1', p:'¿Cuántos partidos políticos hay en España?', o:['Ninguno','Uno','Muchos'], c:2, exp:'En España existe una democracia pluripartidista, con muchos partidos políticos a nivel nacional y autonómico.' },
  { id:'n1094', tema:'tarea1', p:'¿Dónde tiene lugar la investidura del presidente del Gobierno?', o:['En el Palacio de la Moncloa','En el Congreso de los Diputados','En el Senado'], c:1, exp:'La investidura del presidente del Gobierno tiene lugar en el Congreso de los Diputados, donde los diputados votan.' },
  { id:'n1095', tema:'tarea1', p:'¿Quién tiene el mando supremo de las Fuerzas Armadas?', o:['El rey','El presidente del Gobierno','El ministro de Defensa'], c:0, exp:'El rey es el mando supremo de las Fuerzas Armadas, según el artículo 62 de la Constitución.' },
  { id:'n1096', tema:'tarea1', p:'¿Quién es el representante del Estado en una comunidad autónoma?', o:['El presidente de la comunidad autónoma','El delegado del Gobierno','El presidente de la Asamblea autonómica'], c:1, exp:'El delegado del Gobierno representa al Gobierno central en cada comunidad autónoma.' },
  { id:'n1097', tema:'tarea1', p:'¿Cuántas provincias hay en España?', o:['45','50','55'], c:1, exp:'España está dividida en 50 provincias.' },
  { id:'n1098', tema:'tarea1', p:'La enseñanza de las lenguas cooficiales es competencia…', o:['del Estado','de la comunidad autónoma','de la provincia'], c:1, exp:'La enseñanza de las lenguas cooficiales es competencia de la comunidad autónoma correspondiente.' },
  { id:'n1099', tema:'tarea1', p:'El poder ejecutivo corresponde…', o:['al Gobierno del Estado','al Congreso y al Senado','a los jueces y magistrados'], c:0, exp:'El poder ejecutivo corresponde al Gobierno, encabezado por el presidente.' },
  { id:'n1100', tema:'tarea1', p:'¿Cuántas cámaras hay en el Parlamento español?', o:['Una','Dos','Tres'], c:1, exp:'El Parlamento español (Cortes Generales) tiene dos cámaras: el Congreso de los Diputados y el Senado.' },
  { id:'n1101', tema:'tarea1', p:'El suministro de agua y el alumbrado de las ciudades es competencia de…', o:['el ayuntamiento','el Gobierno autonómico','el Ministerio de Obras Públicas y Urbanismo'], c:0, exp:'Los ayuntamientos son responsables de los servicios municipales básicos como el agua y el alumbrado público.' },
  { id:'n1102', tema:'tarea1', p:'En materias como nacionalidad, inmigración, emigración o extranjería solo tiene competencia…', o:['el Estado','las comunidades autónomas','los ayuntamientos'], c:0, exp:'La nacionalidad, inmigración, emigración y extranjería son competencias exclusivas del Estado.' },
  { id:'n1103', tema:'tarea1', p:'¿Cuántas mujeres han sido presidentas de Gobierno en España?', o:['Ninguna','Una','Dos'], c:0, exp:'Hasta 2025, ninguna mujer ha ocupado el cargo de presidenta del Gobierno de España.' },
  { id:'n1104', tema:'tarea1', p:'Las relaciones internacionales son competencia de…', o:['el Estado','las comunidades autónomas','los ayuntamientos'], c:0, exp:'Las relaciones internacionales son competencia exclusiva del Estado.' },
  { id:'n1105', tema:'tarea1', p:'El Ayuntamiento está formado por el alcalde y…', o:['los concejales','los diputados','los senadores'], c:0, exp:'El Ayuntamiento está formado por el alcalde, que lo preside, y los concejales elegidos por los ciudadanos.' },
  { id:'n1106', tema:'tarea1', p:'¿Quiénes forman el gobierno de las comunidades autónomas?', o:['El presidente y los ministros','El alcalde y los concejales','El presidente y los consejeros'], c:2, exp:'El gobierno de cada comunidad autónoma está formado por el presidente y los consejeros.' },
  { id:'n1107', tema:'tarea1', p:'¿Cuál es el órgano de gobierno en los municipios?', o:['El ayuntamiento','La diputación','El cabildo'], c:0, exp:'El ayuntamiento es el órgano de gobierno, administración y representación del municipio.' },
  { id:'n1108', tema:'tarea1', p:'¿Cómo se llaman los órganos de gobierno de las provincias españolas?', o:['Cabildos','Consejos insulares','Diputaciones'], c:2, exp:'Las diputaciones provinciales son los órganos de gobierno de las provincias españolas.' },
  { id:'n1109', tema:'tarea1', p:'¿Cuál es el órgano superior del poder ejecutivo?', o:['El Gobierno','Las Fuerzas Armadas','Las Cortes Generales'], c:0, exp:'El Gobierno es el órgano superior del poder ejecutivo.' },
  { id:'n1110', tema:'tarea1', p:'El idioma español también se llama…', o:['aragonés','castellano','leonés'], c:1, exp:'El español también recibe el nombre de castellano, que es el nombre que se le da en la Constitución.' },
  { id:'n1111', tema:'tarea1', p:'¿A quiénes se elige en las elecciones al Parlamento Europeo?', o:['A los ministros europeos','A los consejeros delegados','A los eurodiputados'], c:2, exp:'En las elecciones al Parlamento Europeo se eligen los eurodiputados que representan a los ciudadanos europeos.' },
  { id:'n1112', tema:'tarea1', p:'Los españoles pueden votar a partir de los…', o:['16 años','18 años','21 años'], c:1, exp:'En España el derecho al voto se adquiere a los 18 años, con la mayoría de edad.' },
  { id:'n1113', tema:'tarea1', p:'Algunos ciudadanos extranjeros pueden votar en las elecciones…', o:['municipales','autonómicas','generales'], c:0, exp:'Los ciudadanos de países de la UE y algunos países con convenio pueden votar en las elecciones municipales.' },
  { id:'n1114', tema:'tarea1', p:'¿Quién controla la gestión financiera del Estado?', o:['El Banco de España','La Agencia Tributaria','El Tribunal de Cuentas'], c:2, exp:'El Tribunal de Cuentas es el supremo órgano fiscalizador de las cuentas y la gestión económica del Estado.' },
  { id:'n1115', tema:'tarea1', p:'¿A quiénes se elige en las elecciones generales?', o:['A los senadores y diputados','A los eurodiputados','A los concejales'], c:0, exp:'En las elecciones generales se eligen los diputados del Congreso y los senadores del Senado.' },
  { id:'n1116', tema:'tarea1', p:'¿Cuántos miembros tiene el Congreso de los Diputados?', o:['300','350','400'], c:1, exp:'El Congreso de los Diputados está formado por 350 diputados elegidos por sufragio universal.' },
  { id:'n1117', tema:'tarea1', p:'Los municipios y provincias forman parte de la Administración…', o:['autonómica','local','central'], c:1, exp:'Los municipios y las provincias forman parte de la Administración local.' },
  { id:'n1118', tema:'tarea1', p:'La comunidad autónoma más poblada de España es…', o:['Andalucía','Cataluña','Castilla y León'], c:0, exp:'Andalucía es la comunidad autónoma más poblada de España.' },
  { id:'n1119', tema:'tarea1', p:'¿Cómo se llama la organización que defiende los intereses de los trabajadores?', o:['Asociación','Partido','Sindicato'], c:2, exp:'Los sindicatos son organizaciones que defienden los intereses de los trabajadores.' },
  { id:'n1120', tema:'tarea1', p:'¿Quién elige al presidente del Gobierno?', o:['El Congreso de los Diputados','El rey','El Tribunal Supremo'], c:0, exp:'El Congreso de los Diputados elige al presidente del Gobierno a través de la investidura.' },

  /* ── TAREA 2: Derechos y deberes fundamentales (36 preguntas — Verdadero/Falso) ── */

  { id:'n2001', tema:'tarea2', p:'En España, la Constitución obliga a todos los ciudadanos a practicar una religión.', o:['Verdadero','Falso'], c:1, exp:'Falso. España es un Estado aconfesional. La Constitución garantiza la libertad religiosa; nadie puede ser obligado a practicar ninguna religión.' },
  { id:'n2002', tema:'tarea2', p:'Los españoles que obtienen la nacionalidad por residencia deben esperar tres años para poder votar en las elecciones.', o:['Verdadero','Falso'], c:1, exp:'Falso. Una vez obtenida la nacionalidad española, se puede votar en las próximas elecciones sin período de espera.' },
  { id:'n2003', tema:'tarea2', p:'En España, la Constitución prohíbe la tortura y la pena de muerte.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 15 prohíbe expresamente la tortura y los tratos inhumanos. La pena de muerte fue abolida.' },
  { id:'n2004', tema:'tarea2', p:'El funcionamiento de los partidos políticos tiene que ser democrático.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 6 de la Constitución establece que la estructura interna y el funcionamiento de los partidos deben ser democráticos.' },
  { id:'n2005', tema:'tarea2', p:'Se puede obligar a alguien a decir cuáles son sus ideas políticas o religiosas.', o:['Verdadero','Falso'], c:1, exp:'Falso. El artículo 16 garantiza la libertad ideológica y religiosa. Nadie puede ser obligado a declarar sobre sus creencias.' },
  { id:'n2006', tema:'tarea2', p:'Se puede limitar a una persona el derecho a entrar y salir libremente de España por motivos ideológicos.', o:['Verdadero','Falso'], c:1, exp:'Falso. El artículo 19 garantiza la libertad de circulación. No se puede limitar por motivos ideológicos.' },
  { id:'n2007', tema:'tarea2', p:'La Educación Primaria (de 6 a 12 años) es gratuita y obligatoria.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. La Educación Primaria (6-12 años) es de carácter obligatorio y gratuito en España.' },
  { id:'n2008', tema:'tarea2', p:'La Constitución garantiza el derecho de los españoles a una vivienda digna.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 47 reconoce el derecho de todos los españoles a disfrutar de una vivienda digna y adecuada.' },
  { id:'n2009', tema:'tarea2', p:'En España la policía puede entrar en cualquier casa sin resolución judicial en cualquier momento.', o:['Verdadero','Falso'], c:1, exp:'Falso. El artículo 18 establece la inviolabilidad del domicilio. Solo se puede entrar con consentimiento del titular o resolución judicial (excepto en caso de flagrante delito).' },
  { id:'n2010', tema:'tarea2', p:'Se garantiza el secreto de las comunicaciones de los españoles, salvo resolución judicial.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 18.3 garantiza el secreto de las comunicaciones, que solo puede levantarse por resolución judicial.' },
  { id:'n2011', tema:'tarea2', p:'La Constitución reconoce el derecho de los ciudadanos a asociarse libremente.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 22 reconoce el derecho de asociación, dentro de los límites constitucionales.' },
  { id:'n2012', tema:'tarea2', p:'Los profesores pueden enseñar con libertad, dentro de los límites de la Constitución.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 20 reconoce la libertad de cátedra, que permite a los docentes enseñar según sus criterios dentro del marco legal.' },
  { id:'n2013', tema:'tarea2', p:'La Constitución reconoce únicamente los derechos fundamentales de los españoles.', o:['Verdadero','Falso'], c:1, exp:'Falso. La Constitución reconoce derechos tanto a los ciudadanos españoles como a los extranjeros que residen en España.' },
  { id:'n2014', tema:'tarea2', p:'Los ciudadanos deben colaborar con los jueces si se lo piden.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 118 establece la obligatoriedad de cumplir las sentencias y colaborar con la Justicia.' },
  { id:'n2015', tema:'tarea2', p:'La ley limita el acceso de terceras personas a datos de carácter personal.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 18.4 establece la protección de datos personales y la Ley Orgánica de Protección de Datos la desarrolla.' },
  { id:'n2016', tema:'tarea2', p:'La libertad de prensa está limitada por el respeto al honor de las personas.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. La libertad de expresión e información tiene límites en el respeto al honor, la intimidad y la presunción de inocencia.' },
  { id:'n2017', tema:'tarea2', p:'En España las causas de separación y divorcio están reguladas por la ley.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 32 establece que la ley regulará las causas de separación y disolución del matrimonio.' },
  { id:'n2018', tema:'tarea2', p:'La atención sanitaria gratuita es solo para personas mayores de 65 años.', o:['Verdadero','Falso'], c:1, exp:'Falso. La atención sanitaria pública es universal y gratuita para todos los residentes en España, sin límite de edad.' },
  { id:'n2019', tema:'tarea2', p:'En España los hombres y las mujeres tienen los mismos derechos.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 14 establece la igualdad ante la ley sin discriminación por razón de sexo.' },
  { id:'n2020', tema:'tarea2', p:'La enseñanza obligatoria consta de dos etapas: Educación Primaria y Educación Secundaria Obligatoria.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. La enseñanza obligatoria en España comprende la Educación Primaria (6-12 años) y la ESO (12-16 años).' },
  { id:'n2021', tema:'tarea2', p:'En España hay una religión oficial.', o:['Verdadero','Falso'], c:1, exp:'Falso. España es un Estado aconfesional; no existe religión oficial del Estado, aunque se mantienen relaciones de cooperación con la Iglesia Católica.' },
  { id:'n2022', tema:'tarea2', p:'La atención sanitaria pública es gratuita.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. La atención sanitaria pública es gratuita para todos los residentes en España.' },
  { id:'n2023', tema:'tarea2', p:'La enseñanza básica en España es solo para los extranjeros.', o:['Verdadero','Falso'], c:1, exp:'Falso. La enseñanza básica es obligatoria y gratuita para todos los niños, españoles y extranjeros, que residen en España.' },
  { id:'n2024', tema:'tarea2', p:'En España está reconocido el derecho de asociación.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 22 de la Constitución reconoce el derecho de asociación.' },
  { id:'n2025', tema:'tarea2', p:'Los sindicatos pueden participar en negociaciones con empresarios y con el Gobierno.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 37 reconoce el derecho a la negociación colectiva entre sindicatos y empresarios.' },
  { id:'n2026', tema:'tarea2', p:'Los trabajadores tienen derecho a hacer huelga.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 28.2 reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses.' },
  { id:'n2027', tema:'tarea2', p:'La libertad ideológica está garantizada solo en parte del territorio nacional.', o:['Verdadero','Falso'], c:1, exp:'Falso. La libertad ideológica, religiosa y de culto está garantizada en todo el territorio español.' },
  { id:'n2028', tema:'tarea2', p:'Todos los ciudadanos tienen acceso al sistema de Seguridad Social público, excepto si están desempleados.', o:['Verdadero','Falso'], c:1, exp:'Falso. El artículo 41 establece que los poderes públicos mantendrán un régimen público de Seguridad Social para todos los ciudadanos, especialmente para quienes no tienen trabajo.' },
  { id:'n2029', tema:'tarea2', p:'Todos tienen derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 45 reconoce el derecho a un medio ambiente adecuado y establece el deber de conservarlo.' },
  { id:'n2030', tema:'tarea2', p:'En España, los poderes públicos deben proteger la salud y promover el deporte.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 43 establece que los poderes públicos fomentarán la educación sanitaria, la educación física y el deporte.' },
  { id:'n2031', tema:'tarea2', p:'La enseñanza básica en España es obligatoria y gratuita.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. La enseñanza básica (Primaria y ESO) es obligatoria y gratuita en España.' },
  { id:'n2032', tema:'tarea2', p:'La ley prohíbe la discriminación por cualquier circunstancia personal o social.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 14 establece que los españoles son iguales ante la ley sin discriminación por nacimiento, raza, sexo, religión u otra condición.' },
  { id:'n2033', tema:'tarea2', p:'En España, los ciudadanos pueden desplazarse libremente por todo el territorio nacional.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 19 reconoce el derecho de los españoles a circular libremente por el territorio nacional.' },
  { id:'n2034', tema:'tarea2', p:'Los jueces administran la justicia en España según las indicaciones del Gobierno.', o:['Verdadero','Falso'], c:1, exp:'Falso. El artículo 117 establece que los jueces son independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.' },
  { id:'n2035', tema:'tarea2', p:'Los españoles deben ayudar en los casos de catástrofe o calamidad pública.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. Los ciudadanos tienen el deber de colaborar en situaciones de catástrofe o calamidad pública.' },
  { id:'n2036', tema:'tarea2', p:'En España los ciudadanos pueden elegir en qué ciudad quieren vivir.', o:['Verdadero','Falso'], c:0, exp:'Verdadero. El artículo 19 reconoce el derecho a elegir libremente la residencia dentro del territorio nacional.' },

  /* ── TAREA 3: Organización territorial y geografía (24 preguntas) ── */

  { id:'n3001', tema:'tarea3', p:'¿Dónde están Cáceres y Badajoz?', o:['En el Principado de Asturias','En Andalucía','En Extremadura'], c:2, exp:'Cáceres y Badajoz son las dos provincias de la comunidad autónoma de Extremadura.' },
  { id:'n3002', tema:'tarea3', p:'¿Cuál es la capital de la Comunidad Valenciana?', o:['Alicante','Castellón','Valencia'], c:2, exp:'Valencia es la capital de la Comunidad Valenciana.' },
  { id:'n3003', tema:'tarea3', p:'¿Dónde están las islas Baleares?', o:['En el mar Cantábrico','En el mar Mediterráneo','En el océano Atlántico'], c:1, exp:'Las Islas Baleares están en el mar Mediterráneo, al este de la Península Ibérica.' },
  { id:'n3004', tema:'tarea3', p:'¿Cómo se llama la extensa llanura situada en el centro de la península ibérica?', o:['Marisma','Cordillera','Meseta'], c:2, exp:'La Meseta Central es la gran planicie que ocupa el centro de la Península Ibérica, a una altitud media de 600-700 metros.' },
  { id:'n3005', tema:'tarea3', p:'El parque nacional de Ordesa está en…', o:['Aragón','Navarra','Castilla-La Mancha'], c:0, exp:'El Parque Nacional de Ordesa y Monte Perdido está en el Pirineo aragonés, en la provincia de Huesca.' },
  { id:'n3006', tema:'tarea3', p:'¿En qué comunidad autónoma están Guadalajara y Cuenca?', o:['En Castilla y León','En Castilla-La Mancha','En Cantabria'], c:1, exp:'Guadalajara y Cuenca son provincias de Castilla-La Mancha.' },
  { id:'n3007', tema:'tarea3', p:'¿Qué comunidad autónoma tiene como capital Santiago de Compostela?', o:['Galicia','Asturias','Cantabria'], c:0, exp:'Santiago de Compostela es la capital de la comunidad autónoma de Galicia.' },
  { id:'n3008', tema:'tarea3', p:'¿Dónde está Almería?', o:['En Andalucía','En Canarias','En Aragón'], c:0, exp:'Almería es una provincia de la comunidad autónoma de Andalucía, al sureste de España.' },
  { id:'n3009', tema:'tarea3', p:'La capital de la comunidad autónoma de Galicia es…', o:['A Coruña','Vigo','Santiago de Compostela'], c:2, exp:'Santiago de Compostela es la capital de Galicia, ciudad conocida por ser destino del Camino de Santiago.' },
  { id:'n3010', tema:'tarea3', p:'¿Cuál de estos ríos desemboca en el mar Mediterráneo?', o:['El Tajo','El Júcar','El Duero'], c:1, exp:'El río Júcar desemboca en el mar Mediterráneo, en la Comunidad Valenciana.' },
  { id:'n3011', tema:'tarea3', p:'¿Dónde está el monte Aneto?', o:['En los Pirineos','En el Sistema Central','En Sierra Nevada'], c:0, exp:'El Aneto, con 3404 m, es la cima más alta de los Pirineos y de España peninsular, en la provincia de Huesca.' },
  { id:'n3012', tema:'tarea3', p:'La ciudad de Vitoria es la sede administrativa de…', o:['Navarra','País Vasco','La Rioja'], c:1, exp:'Vitoria-Gasteiz es la capital y sede del Gobierno del País Vasco.' },
  { id:'n3013', tema:'tarea3', p:'España se divide en…', o:['departamentos y regiones','comunidades y ciudades autónomas','regiones autónomas y distritos'], c:1, exp:'España se divide en 17 comunidades autónomas y 2 ciudades autónomas (Ceuta y Melilla).' },
  { id:'n3014', tema:'tarea3', p:'El parque nacional de Aigüestortes está en…', o:['Cataluña','Aragón','Castilla y León'], c:0, exp:'El Parque Nacional de Aigüestortes i Estany de Sant Maurici está en los Pirineos catalanes, en la provincia de Lleida.' },
  { id:'n3015', tema:'tarea3', p:'En el norte de África están Ceuta y…', o:['Almería','Melilla','Cádiz'], c:1, exp:'Ceuta y Melilla son las dos ciudades autónomas españolas situadas en el norte de África.' },
  { id:'n3016', tema:'tarea3', p:'¿En qué lugar de España hay un clima que se caracteriza por inviernos fríos y veranos muy calurosos?', o:['Canarias','Comunidad Valenciana','Madrid'], c:2, exp:'Madrid y el interior peninsular tienen un clima continental, con inviernos fríos y veranos muy calurosos.' },
  { id:'n3017', tema:'tarea3', p:'¿Cuál de estos ríos desemboca en el océano Atlántico?', o:['El Guadalquivir','El Manzanares','El Júcar'], c:0, exp:'El Guadalquivir desemboca en el océano Atlántico, en el Parque Nacional de Doñana (Huelva).' },
  { id:'n3018', tema:'tarea3', p:'¿Cuál de estas provincias forma parte de la Comunidad de Castilla y León?', o:['Burgos','Huesca','Guadalajara'], c:0, exp:'Burgos es una de las nueve provincias de Castilla y León, la comunidad autónoma más extensa de España.' },
  { id:'n3019', tema:'tarea3', p:'¿En qué comunidad autónoma está la ciudad de Huesca?', o:['Castilla-La Mancha','Aragón','Extremadura'], c:1, exp:'Huesca es una provincia y ciudad de la comunidad autónoma de Aragón.' },
  { id:'n3020', tema:'tarea3', p:'Canarias tiene un clima…', o:['mediterráneo','oceánico','subtropical'], c:2, exp:'Las Islas Canarias tienen un clima subtropical, con temperaturas suaves todo el año y escasas precipitaciones.' },
  { id:'n3021', tema:'tarea3', p:'El principal río que desemboca en el mar Mediterráneo es el…', o:['Ebro','Duero','Tajo'], c:0, exp:'El Ebro es el río más caudaloso de España y el principal que desemboca en el mar Mediterráneo, en el delta del Ebro (Tarragona).' },
  { id:'n3022', tema:'tarea3', p:'España está entre los países de Europa más…', o:['lluviosos','montañosos','fríos'], c:1, exp:'España es el segundo país más montañoso de Europa, después de Suiza, con una altitud media de 660 metros.' },
  { id:'n3023', tema:'tarea3', p:'¿En qué provincia está el parque nacional de Monfragüe?', o:['En Cáceres','En Murcia','En Ciudad Real'], c:0, exp:'El Parque Nacional de Monfragüe está en la provincia de Cáceres, en Extremadura.' },
  { id:'n3024', tema:'tarea3', p:'¿Cuál es la capital de la comunidad autónoma de Extremadura?', o:['Cáceres','Badajoz','Mérida'], c:2, exp:'Mérida es la capital de la comunidad autónoma de Extremadura.' },

  /* ── TAREA 4: Cultura e historia de España (36 preguntas) ── */

  { id:'n4001', tema:'tarea4', p:'Los personajes principales de la novela el Quijote son don Quijote y…', o:['Don Juan','Sancho Panza','Doña Inés'], c:1, exp:'Don Quijote de la Mancha, obra de Miguel de Cervantes, tiene como protagonistas a Don Quijote y su escudero Sancho Panza.' },
  { id:'n4002', tema:'tarea4', p:'¿Qué científica española es reconocida por sus investigaciones?', o:['Almudena Grandes','Montserrat Caballé','Margarita Salas'], c:2, exp:'Margarita Salas fue una bioquímica española pionera en biología molecular, reconocida internacionalmente por sus investigaciones.' },
  { id:'n4003', tema:'tarea4', p:'¿Quién escribió La casa de Bernarda Alba?', o:['Federico García Lorca','Miguel de Cervantes','Antonio Machado'], c:0, exp:'Federico García Lorca escribió La casa de Bernarda Alba, una de las obras más importantes del teatro español del siglo XX.' },
  { id:'n4004', tema:'tarea4', p:'¿Quién escribió Nada, una novela sobre la posguerra española?', o:['Carmen Laforet','Ana María Matute','María Dueñas'], c:0, exp:'Carmen Laforet escribió Nada (1945), novela ganadora del Premio Nadal que retrata la Barcelona de la posguerra.' },
  { id:'n4005', tema:'tarea4', p:'¿Qué músico compuso El amor brujo?', o:['Manuel de Falla','Isaac Albéniz','Joaquín Rodrigo'], c:0, exp:'Manuel de Falla compuso El amor brujo (1915), una de las obras cumbres de la música española.' },
  { id:'n4006', tema:'tarea4', p:'¿Qué es típico en la Noche de San Juan?', o:['Comer uvas','Encender hogueras','Regalar libros'], c:1, exp:'En la Noche de San Juan (23 de junio) es tradición encender hogueras, especialmente en el norte y el levante de España.' },
  { id:'n4007', tema:'tarea4', p:'¿Cuál es el instrumento más característico de la música flamenca?', o:['La gaita','La guitarra','El piano'], c:1, exp:'La guitarra española es el instrumento más característico del flamenco, junto al cante y el baile.' },
  { id:'n4008', tema:'tarea4', p:'Isabel Coixet es una…', o:['cantante pop','bailarina clásica','directora de cine'], c:2, exp:'Isabel Coixet es una de las directoras de cine más reconocidas de España, con películas como La vida secreta de las palabras.' },
  { id:'n4009', tema:'tarea4', p:'Una de las cantantes españolas más famosas actualmente es…', o:['Rosalía','Marisol','Lola Flores'], c:0, exp:'Rosalía es una cantante y compositora española de música pop y flamenco, con proyección internacional.' },
  { id:'n4010', tema:'tarea4', p:'¿En qué ciudad de España hay una mezquita que es Patrimonio de la Humanidad?', o:['Santiago de Compostela','Madrid','Córdoba'], c:2, exp:'La Mezquita-Catedral de Córdoba es Patrimonio de la Humanidad desde 1984, símbolo de la convivencia de culturas en Al-Ándalus.' },
  { id:'n4011', tema:'tarea4', p:'¿En qué ciudad de España se encuentra La Alhambra, que es Patrimonio de la Humanidad?', o:['En Sevilla','En Córdoba','En Granada'], c:2, exp:'La Alhambra es un conjunto palaciego y fortaleza situado en Granada, declarado Patrimonio de la Humanidad.' },
  { id:'n4012', tema:'tarea4', p:'¿Cuál es el nombre de la directora española que ha destacado por su mirada crítica y por modernizar el cine nacional?', o:['Pilar Miró','Sara Baras','Penélope Cruz'], c:0, exp:'Pilar Miró fue una directora de cine y televisión española, fundamental en la modernización del cine español en los años 80.' },
  { id:'n4013', tema:'tarea4', p:'¿Qué novela de éxito ha escrito Irene Vallejo?', o:['El infinito en un junco','El tiempo entre costuras','El camino'], c:0, exp:'El infinito en un junco (2019) de Irene Vallejo es un ensayo sobre la historia del libro y la lectura que se convirtió en un gran éxito.' },
  { id:'n4014', tema:'tarea4', p:'¿Cómo se llama la mayor institución pública dedicada a la investigación en España?', o:['Real Academia Española (RAE)','Consejo Superior de Investigaciones Científicas (CSIC)','La Sociedad General de Autores (SGAE)'], c:1, exp:'El Consejo Superior de Investigaciones Científicas (CSIC) es la mayor institución pública dedicada a la investigación científica en España.' },
  { id:'n4015', tema:'tarea4', p:'Paco de Lucía fue un famoso…', o:['científico','guitarrista','pintor'], c:1, exp:'Paco de Lucía fue un guitarrista flamenco español, considerado uno de los mejores guitarristas de la historia.' },
  { id:'n4016', tema:'tarea4', p:'¿Qué celebramos el 24 de diciembre?', o:['Carnaval','Nochebuena','San Juan'], c:1, exp:'El 24 de diciembre se celebra Nochebuena, víspera de Navidad, con reuniones familiares y cenas tradicionales.' },
  { id:'n4017', tema:'tarea4', p:'Juan Mari Arzak es un famoso…', o:['escritor','músico','cocinero'], c:2, exp:'Juan Mari Arzak es un chef español considerado uno de los grandes maestros de la cocina vasca y de la nueva cocina española.' },
  { id:'n4018', tema:'tarea4', p:'¿Quién fue Clara Campoamor?', o:['Una defensora de los derechos de la mujer','Una cantante lírica','Una directora de cine'], c:0, exp:'Clara Campoamor fue una abogada y política española que defendió el voto femenino, conseguido en 1931.' },
  { id:'n4019', tema:'tarea4', p:'¿Qué canciones típicas se cantan en Navidad?', o:['Flamenco','Villancicos','Jotas'], c:1, exp:'Los villancicos son canciones tradicionales que se cantan en España durante la Navidad.' },
  { id:'n4020', tema:'tarea4', p:'La Liga y la Copa del Rey son competiciones de…', o:['natación','atletismo','fútbol'], c:2, exp:'La Liga española y la Copa del Rey son las principales competiciones de fútbol en España.' },
  { id:'n4021', tema:'tarea4', p:'¿Quién ha recibido el premio Nobel de Literatura?', o:['María Zambrano','Pablo Picasso','Vicente Aleixandre'], c:2, exp:'Vicente Aleixandre recibió el Premio Nobel de Literatura en 1977, poeta de la Generación del 27.' },
  { id:'n4022', tema:'tarea4', p:'¿Qué fiesta se celebra en Pamplona el 7 de julio?', o:['Los sanfermines','Las Fallas','La Feria de Abril'], c:0, exp:'Los Sanfermines se celebran en Pamplona del 6 al 14 de julio, con los famosos encierros de toros.' },
  { id:'n4023', tema:'tarea4', p:'Teresa Perales y Daniel Molina son…', o:['campeones paraolímpicos','músicos famosos','artistas de cine'], c:0, exp:'Teresa Perales y Daniel Molina son deportistas españoles de alto nivel con múltiples medallas paralímpicas.' },
  { id:'n4024', tema:'tarea4', p:'¿Qué toman los españoles la noche del 31 de diciembre para celebrar el cambio de año?', o:['Lentejas','Uvas','Aceitunas'], c:1, exp:'La tradición española de Nochevieja consiste en tomar 12 uvas al ritmo de las campanadas de medianoche.' },
  { id:'n4025', tema:'tarea4', p:'¿Qué mujer es autora del cuadro La verbena?', o:['Maruja Mallo','Carmen Maura','Clara Lago'], c:0, exp:'Maruja Mallo fue una pintora gallega vanguardista, autora de La verbena (1927), obra icónica del surrealismo español.' },
  { id:'n4026', tema:'tarea4', p:'¿En qué museo español puedes ver el cuadro Guernica de Picasso?', o:['Museo del Prado','Museo Reina Sofía','Museo Thyssen-Bornemisza'], c:1, exp:'El Guernica de Pablo Picasso se expone en el Museo Nacional Centro de Arte Reina Sofía, en Madrid.' },
  { id:'n4027', tema:'tarea4', p:'¿Qué escritora española escribe en otra lengua oficial de España?', o:['Mercè Rodoreda','Almudena Grandes','Ana María Matute'], c:0, exp:'Mercè Rodoreda fue una escritora catalana que escribió en catalán, autora de La plaça del Diamant.' },
  { id:'n4028', tema:'tarea4', p:'¿Qué tres culturas convivieron en la España medieval?', o:['La cristiana, la judía y la musulmana','La fenicia, la judía y la musulmana','La griega, la cristiana y la judía'], c:0, exp:'En la España medieval convivieron tres culturas: la cristiana, la judía y la musulmana, especialmente durante Al-Ándalus.' },
  { id:'n4029', tema:'tarea4', p:'El 6 de diciembre se celebra en España…', o:['el Día de la Constitución','la llegada de Colón a América','el Día del Libro'], c:0, exp:'El 6 de diciembre es el Día de la Constitución, en conmemoración de su aprobación en referéndum en 1978.' },
  { id:'n4030', tema:'tarea4', p:'¿Qué ciudad fue un centro científico en Al-Ándalus, donde se estudiaba medicina y astronomía?', o:['Barcelona','Madrid','Córdoba'], c:2, exp:'Córdoba fue la capital de Al-Ándalus y un gran centro del saber medieval, donde se cultivaban la medicina, la astronomía y la filosofía.' },
  { id:'n4031', tema:'tarea4', p:'¿En qué ciudad española está el Museo Guggenheim?', o:['Bilbao','Madrid','Valencia'], c:0, exp:'El Museo Guggenheim Bilbao, diseñado por Frank Gehry, se inauguró en 1997 y es uno de los museos de arte contemporáneo más visitados del mundo.' },
  { id:'n4032', tema:'tarea4', p:'El Premio Cervantes se da a…', o:['actores','escritores','pintores'], c:1, exp:'El Premio Cervantes es el máximo galardón de las letras hispanas, concedido a escritores en lengua española.' },
  { id:'n4033', tema:'tarea4', p:'¿Qué premio reconoce a los mejores actores y películas?', o:['Premio Goya','Premio Nobel','Premio Cervantes'], c:0, exp:'Los Premios Goya son los galardones del cine español, concedidos por la Academia de las Artes y las Ciencias Cinematográficas de España.' },
  { id:'n4034', tema:'tarea4', p:'¿Qué premios promueven en España valores científicos, culturales y humanísticos?', o:['Los Premios Cervantes','Los Premios Princesa de Asturias','Los Premios Goya'], c:1, exp:'Los Premios Princesa de Asturias reconocen valores científicos, culturales, sociales y humanísticos en el ámbito internacional.' },
  { id:'n4035', tema:'tarea4', p:'¿Cuál de estos deportes es muy popular en España?', o:['El fútbol','El esquí','El golf'], c:0, exp:'El fútbol es el deporte más popular en España, con millones de aficionados y equipos de renombre mundial.' },
  { id:'n4036', tema:'tarea4', p:'¿Cuál de estos deportistas juega al tenis?', o:['Pau Gasol','Carlos Sainz','Carlos Alcaraz'], c:2, exp:'Carlos Alcaraz es un tenista español, número 1 del mundo y ganador de varios torneos de Grand Slam.' }

